from itertools import permutations

def is_costas_array(perm):
    n = len(perm)
    vectors = set()
    for i in range(n):
        for j in range(i+1, n):
            dc = j - i
            dr = perm[j] - perm[i]
            if (dr, dc) in vectors:
                return False
            vectors.add((dr, dc))
    return True

# Search for a Costas array of order 6
n = 6
for perm in permutations(range(n)):
    if is_costas_array(perm):
        print(f"Found Costas array: {list(perm)}")
        break
else:
    print("No Costas array of order 6 found")
